def diagnose(chains, prob=0.89):
    if len(chains) < 2:
        raise ValueError("need at least two chains to compare")
    n = len(chains[0])
    if n < 2:
        raise ValueError("need at least two draws per chain")
    if any(len(c) != n for c in chains):
        raise ValueError("all chains must have the same number of draws")
    if not 0 < prob < 1:
        raise ValueError("prob must be strictly between 0 and 1")
    m = len(chains)
    means = [sum(c) / n for c in chains]
    within = [sum((x - mu) ** 2 for x in c) / (n - 1) for c, mu in zip(chains, means)]
    W = sum(within) / m
    if W == 0:
        raise ValueError("every chain is constant, so R-hat is undefined")
    grand = sum(means) / m
    B = n * sum((mu - grand) ** 2 for mu in means) / (m - 1)
    var_hat = (n - 1) / n * W + B / n
    rhat = (var_hat / W) ** 0.5
    pooled = sorted(x for c in chains for x in c)
    total = len(pooled)
    tail = (1 - prob) / 2
    def pick(q):
        index = int(round(q * (total - 1)))
        return pooled[max(0, min(total - 1, index))]
    return {"rhat": rhat, "mean": sum(pooled) / total,
            "low": pick(tail), "high": pick(1 - tail)}
